class Solution:
 def isLongPressedName(self,name,typed):
  i=j=0
  while j<len(typed):
   if i<len(name) and name[i]==typed[j]:i+=1;j+=1
   elif j>0 and typed[j]==typed[j-1]:j+=1
   else:return False
  return i==len(name)

class Solution:
 def numUniqueEmails(self,emails):
  out=set()
  for email in emails:
   local,domain=email.split('@');local=local.split('+',1)[0].replace('.','');out.add(local+'@'+domain)
  return len(out)

from collections import deque
class RecentCounter:
 def __init__(self):self.q=deque()
 def ping(self,t):
  self.q.append(t)
  while self.q[0]<t-3000:self.q.popleft()
  return len(self.q)

class Solution:
 def reorderLogFiles(self,logs):
  letters=[];digits=[]
  for log in logs:
   if log.split()[1][0].isdigit():digits.append(log)
   else:letters.append(log)
  letters.sort(key=lambda x:(x.split(' ',1)[1],x.split(' ',1)[0]))
  return letters+digits

class Solution:
 def rangeSumBST(self,root,low,high):
  if root is None:return 0
  total=root.val if low<=root.val<=high else 0
  if root.val>low:total+=self.rangeSumBST(root.left,low,high)
  if root.val<high:total+=self.rangeSumBST(root.right,low,high)
  return total

class Solution:
 def minDeletionSize(self,strs):
  if not strs:return 0
  return sum(any(strs[r][c]<strs[r-1][c] for r in range(1,len(strs))) for c in range(len(strs[0])))

class Solution:
 def isAlienSorted(self,words,order):
  rank={c:i for i,c in enumerate(order)}
  for a,b in zip(words,words[1:]):
   for x,y in zip(a,b):
    if rank[x]<rank[y]:break
    if rank[x]>rank[y]:return False
   else:
    if len(a)>len(b):return False
  return True

