class Solution:
 def isUnivalTree(self,root):
  if root is None:return True
  stack=[root]
  while stack:
   n=stack.pop()
   if n.val!=root.val:return False
   if n.left:stack.append(n.left)
   if n.right:stack.append(n.right)
  return True
